// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, 1e24);
        vm.deal(address(this), amount);
        // deposit through the fallback, which increments depositsCount
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep);

        uint256 cBalanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = address(this).balance;

        // owner (the test contract, = msg.sender at deploy) drains the contract
        c.withdrawAll();

        // Rule: after withdrawAll, the owner has received exactly the balance c held.
        assertTrue(address(this).balance == ownerBalanceBefore + cBalanceBefore);
    }

    receive() external payable {}
}
